<script setup>
import { computed, onMounted, ref } from 'vue'; import { api } from '../api'; import RecipeTile from '../components/RecipeTile.vue'; import { Plus, ShoppingBasket, Trash2, Wine } from 'lucide-vue-next'; import { emitMotion } from '../motion'
const items=ref([]),newItem=ref(''),matches=ref({ready:[],nearby:[]}),loading=ref(true),saving=ref(false),error=ref('')
const categories=[{name:'基酒',values:['金酒','伏特加','朗姆','龙舌兰','威士忌','白兰地']},{name:'利口酒',values:['君度','金巴利','咖啡利口酒','味美思']},{name:'辅料',values:['柠檬汁','青柠汁','糖浆','苏打水','汤力水','薄荷','苦精']}]
const shopping=computed(()=>{const count={};matches.value.nearby.slice(0,12).forEach(r=>r.missing_ingredients.forEach(x=>count[x]=(count[x]||0)+1));return Object.entries(count).sort((a,b)=>b[1]-a[1]).slice(0,12)})
async function load(){loading.value=true;error.value='';try{const [inventory,data]=await Promise.all([api.me.inventory(),api.me.matches()]);items.value=inventory.items;matches.value=data}catch(e){error.value=e.message}finally{loading.value=false}}
async function save(next){const previous=new Set(items.value),normalized=[...new Set(next.map(x=>x.trim()).filter(Boolean))],added=normalized.find(x=>!previous.has(x)),removed=items.value.find(x=>!normalized.includes(x));saving.value=true;try{items.value=(await api.me.setInventory(normalized)).items;matches.value=await api.me.matches();emitMotion(added?'shelf-in':'shelf-out',{label:added||removed||'inventory'})}catch(e){error.value=e.message}finally{saving.value=false}}
function add(name=newItem.value){if(!name.trim()||items.value.includes(name.trim()))return;save([...items.value,name.trim()]);newItem.value=''}function remove(name){save(items.value.filter(x=>x!==name))}
onMounted(load)
</script>
<template><div class="page"><header class="page-head"><div><h1>我的酒柜</h1><p>维护实际库存，立即查看可调配方、缺失材料与替代建议。</p></div><span class="chip green"><Wine :size="14"/>{{items.length}} 种材料</span></header><div v-if="error" class="error-box">{{error}}</div>
<section class="inventory-layout"><div class="panel panel-pad stock"><h2 class="section-title">当前库存</h2><div class="add-row"><input class="input" v-model="newItem" placeholder="输入材料名称" @keydown.enter="add()"/><button class="btn primary" :disabled="saving" @click="add()"><Plus :size="16"/>添加</button></div><div class="stock-list"><div v-if="!items.length" class="state"><div><strong>酒柜还是空的</strong>从下方常用材料开始添加。</div></div><span v-for="item in items" :key="item" class="stock-chip">{{item}}<button title="移除" @click="remove(item)"><Trash2 :size="13"/></button></span></div><div class="quick" v-for="group in categories" :key="group.name"><b>{{group.name}}</b><div><button v-for="item in group.values" :key="item" :disabled="items.includes(item)" @click="add(item)">+ {{item}}</button></div></div></div>
<aside class="panel panel-pad shopping"><h2 class="section-title"><ShoppingBasket :size="18"/>购物清单</h2><p class="muted">按可解锁的配方数量排序</p><div v-if="!shopping.length" class="state"><div><strong>暂无缺失材料</strong>添加库存后会自动计算。</div></div><ol v-else><li v-for="([name,count],i) in shopping" :key="name"><span>{{i+1}}</span><b>{{name}}</b><small>可推进 {{count}} 款配方</small><button class="icon-btn" title="加入库存" @click="add(name)"><Plus :size="15"/></button></li></ol></aside></section>
<section class="match-section"><div class="match-head"><div><h2>现在就能调</h2><p>{{matches.ready.length}} 款无需补充材料</p></div></div><div v-if="loading" class="state">正在匹配酒柜...</div><div v-else-if="matches.ready.length" class="grid grid-4"><RecipeTile v-for="r in matches.ready.slice(0,8)" :key="r.id" :recipe="r"/></div><div v-else class="state"><div><strong>暂时没有完全匹配</strong>继续补充材料，或从下方近似配方开始。</div></div></section>
<section class="match-section"><div class="match-head"><div><h2>再补一点就能调</h2><p>优先展示缺失最少的配方</p></div></div><div class="nearby-list"><article v-for="r in matches.nearby.slice(0,10)" :key="r.id" class="panel nearby"><img :src="r.image" :alt="r.name"/><div><h3><router-link :to="`/recipes/${r.id}`">{{r.name_cn||r.name}}</router-link></h3><p>完成度 {{Math.round(r.match_ratio*100)}}%</p><div class="toolbar"><span v-for="m in r.missing_ingredients" :key="m" class="chip amber">缺 {{m}}</span></div><details v-if="Object.keys(r.substitution_suggestions||{}).length"><summary>查看替代建议</summary><p v-for="cards in Object.values(r.substitution_suggestions)" :key="cards[0]?.id">{{cards[0]?.title}}：{{cards[0]?.guidance}}</p></details></div></article></div></section></div></template>
<style scoped>.inventory-layout{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,.7fr);gap:18px}.add-row{display:flex;gap:8px}.stock-list{display:flex;flex-wrap:wrap;gap:7px;margin:16px 0 22px;min-height:46px}.stock-chip{display:flex;align-items:center;gap:6px;background:#e7eee9;border:1px solid #c5d7ca;border-radius:999px;padding:6px 6px 6px 10px;font-size:12px}.stock-chip button{border:0;background:none;color:#65706a;display:grid;place-items:center;padding:2px}.quick{border-top:1px solid var(--line);padding-top:14px;margin-top:14px}.quick b{font-size:12px}.quick>div{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.quick button{border:1px dashed #c4cac6;background:#fff;border-radius:5px;padding:6px 8px;color:#59625d;font-size:11px}.quick button:disabled{opacity:.35}.shopping .section-title{display:flex;align-items:center;gap:7px}.shopping>p{font-size:11px}.shopping ol{list-style:none;padding:0}.shopping li{display:grid;grid-template-columns:24px 1fr auto 34px;align-items:center;gap:6px;padding:8px 0;border-bottom:1px solid #edf0ed}.shopping li>span{width:22px;height:22px;display:grid;place-items:center;background:#f2e6d4;color:#8f5515;border-radius:50%;font-size:10px}.shopping li small{color:var(--muted);font-size:10px}.shopping .icon-btn{width:30px;height:30px}.match-section{margin-top:30px}.match-head h2{font-size:19px;margin:0}.match-head p{color:var(--muted);font-size:12px;margin:5px 0 15px}.nearby-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.nearby{display:grid;grid-template-columns:110px 1fr;overflow:hidden}.nearby>img{width:110px;height:100%;min-height:145px;object-fit:cover}.nearby>div{padding:13px}.nearby h3{margin:0}.nearby>div>p{font-size:11px;color:var(--muted)}.nearby details{font-size:11px;margin-top:9px;color:var(--green)}.nearby details p{color:#4f5853;line-height:1.5;max-height:65px;overflow:hidden}@media(max-width:900px){.inventory-layout{grid-template-columns:1fr}.nearby-list{grid-template-columns:1fr}}@media(max-width:480px){.nearby{grid-template-columns:85px 1fr}.nearby>img{width:85px}}</style>
